// @ts-check
// Some portions generated by Claude Code
//
// Connection is how a user whose server refuses them, fails or holds nothing signs in or picks another server: the
// sidebar and the phone menu offer it whatever the server answers, and its page opens whatever the server answers.
// The refusing and the empty server are stand-ins in front of the real one (server-stand-in.js).
const { test, expect } = require('@playwright/test');
const {
    createSeededRepository,
    deleteRepository,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute,
    workbenchBaseUrl
} = require('./workbench-test-helpers');
const { standInHint, startServerStandIn } = require('./server-stand-in');

const WORKBENCH = workbenchBaseUrl();
const REFUSED = /failed to authenticate to the RDF4J server/;

/** Points this browser's Workbench at the given server, as the Connection page does. */
async function useServer(context, url) {
    await context.addCookies([{ name: 'workbench-server', value: url, url: WORKBENCH + '/' }]);
}

/** The sidebar's links, by name. */
function sidebarLinks(page) {
    return page.locator('#navigation a[data-workbench-nav-href]');
}

/** Opens Connection from the sidebar and checks its page: the server form, naming the given server. */
async function openConnection(page, server) {
    await page.locator('#navigation').getByRole('link', { name: 'Connection' }).click();
    await waitForRoute(page, 'server');
    await expect(page).toHaveURL(/\/repositories\/NONE\/server$/);
    await expect(page.locator('#content h1')).toHaveText('Connect to RDF4J Server');
    await expect(page.locator('#workbench-server')).toHaveValue(server);
}

test.describe('a server that refuses the user', () => {
    const user = 'connection-user';
    const password = 'connection-password';
    const repositoryId = uniqueRepositoryId('connection-recovery');
    /** @type {Awaited<ReturnType<typeof startServerStandIn>>} */
    let refusing;

    test.beforeAll(async ({ request }) => {
        refusing = await startServerStandIn({ user, password });
        await createSeededRepository(request, serverBaseUrl(), repositoryId, { graphs: [] });
    });

    test.afterAll(async ({ request }) => {
        await refusing.close();
        await deleteRepository(request, serverBaseUrl(), repositoryId);
    });

    test('shows its refusal inside the shell, and Connection still opens', async ({ page, context }) => {
        await page.setViewportSize({ width: 1280, height: 900 });
        await useServer(context, refusing.url);
        for (const path of ['NONE/repositories', `${repositoryId}/summary`]) {
            await page.goto(`${WORKBENCH}/repositories/${path}`);
            expect(refusing.accepted(), standInHint(refusing.url)).toBe(true);
            await expect(page.locator('#content'), path).toContainText(REFUSED);
            await expect(sidebarLinks(page), path).toHaveText(['Connection']);
        }
        await openConnection(page, refusing.url);
        await expect(sidebarLinks(page)).toHaveText(['Connection']);
    });

    test('a user who signs in on Connection gets the whole Workbench; wrong credentials keep Connection',
        async ({ page, context }) => {
            await page.setViewportSize({ width: 1280, height: 900 });
            await useServer(context, refusing.url);
            await page.goto(`${WORKBENCH}/repositories/NONE/server`);
            await waitForRoute(page, 'server');

            const signIn = async (secret) => {
                await page.locator('#workbench-server').fill(refusing.url);
                const user = page.locator('#server-user');
                if (!await user.isVisible()) {
                    await page.locator('#server-auth-toggle').click();
                }
                await user.fill('connection-user');
                await page.locator('#server-password').fill(secret);
                await Promise.all([
                    page.waitForURL((url) => !/\/NONE\/server(?:[?#]|$)/.test(url.toString()), { timeout: 15000 }),
                    page.locator('#server-password').press('Enter')
                ]);
            };

            await signIn('not-the-password');
            expect(refusing.accepted(), standInHint(refusing.url)).toBe(true);
            await expect(page.locator('#content')).toContainText(REFUSED);
            await expect(sidebarLinks(page)).toHaveText(['Connection']);

            await openConnection(page, refusing.url);
            await signIn(password);
            await waitForRoute(page, 'repositories');
            await expect(page.locator('#content')).not.toContainText(REFUSED);
            await expect(page.locator('#content')).toContainText(repositoryId);
            for (const name of ['Repositories', 'Create repository', 'Connection', 'Information']) {
                await expect(page.locator('#navigation').getByRole('link', { name, exact: true }), name).toBeVisible();
            }
        });

    test('on a phone the menu sheet still offers Connection', async ({ page, context }) => {
        await page.setViewportSize({ width: 390, height: 844 });
        await useServer(context, refusing.url);
        await page.goto(`${WORKBENCH}/repositories/NONE/repositories`);
        expect(refusing.accepted(), standInHint(refusing.url)).toBe(true);
        await expect(page.locator('#content')).toContainText(REFUSED);
        await page.locator('#workbench-menu-button').click();
        const sheet = page.getByRole('dialog', { name: 'Menu' });
        await expect(sheet).toBeVisible();
        // The menu is the server's, when its Info answers (the pages a signed-in user opened are kept), else Connection.
        const connection = sheet.getByRole('link', { name: 'Connection' });
        await expect(connection).toBeVisible();
        await connection.click();
        await waitForRoute(page, 'server');
        await expect(sheet).toBeHidden();
        await expect(page.locator('#content h1')).toHaveText('Connect to RDF4J Server');
        await expect(page.locator('#workbench-server')).toHaveValue(refusing.url);
    });
});

test.describe('a server without repositories', () => {
    /** @type {Awaited<ReturnType<typeof startServerStandIn>>} */
    let empty;

    test.beforeAll(async () => {
        empty = await startServerStandIn({ noRepositories: true });
    });

    test.afterAll(async () => {
        await empty.close();
    });

    test('lists none, and Connection opens from the sidebar', async ({ page, context }) => {
        await page.setViewportSize({ width: 1280, height: 900 });
        await useServer(context, empty.url);
        await page.goto(`${WORKBENCH}/repositories/NONE/repositories`);
        await waitForRoute(page, 'repositories');
        expect(empty.accepted(), standInHint(empty.url)).toBe(true);
        await expect(page.locator('#content')).toContainText('No repositories are available.');
        await openConnection(page, empty.url);
    });
});

// The Info answer of a page can fail for another reason than a refused user: a server error, a dropped connection.
test.describe('a page whose Info answer fails', () => {
    for (const [failure, answer] of [
        ['a server error', (route) => route.fulfill({ status: 500, contentType: 'text/plain', body: 'Internal error' })],
        ['a dropped connection', (route) => route.abort('connectionreset')]
    ]) {
        test(`with ${failure} is an error inside the shell, and Connection still opens`, async ({ page }) => {
            await page.setViewportSize({ width: 1280, height: 900 });
            await page.route(/\/repositories\/[^/]+\/info(\?.*)?$/, answer);
            await page.goto(`${WORKBENCH}/repositories/NONE/repositories`);
            await waitForRoute(page, 'repositories');
            await expect(page.locator('#content')).toContainText('Unable to load this Workbench page.');
            await expect(sidebarLinks(page)).toHaveText(['Connection']);
            await page.locator('#navigation').getByRole('link', { name: 'Connection' }).click();
            await waitForRoute(page, 'server');
            await expect(page.locator('#content h1')).toHaveText('Connect to RDF4J Server');
            await expect(page.locator('#server-form')).toBeVisible();
            await expect(page.locator('#content')).not.toContainText('Unable to load this Workbench page.');
        });
    }
});
